insert into public.docs (path, collection, data) values
  ('box/mom-s-usal', 'box', '{"at": "2026-10-21T23:00:00Z", "carb": "Rice or rotli", "cuisine": "Indian", "dish": "Mom''s Usal", "id": "box-mom-s-usal", "ingredients": ["dried beans", "oil", "cumin seeds", "hing", "onion", "ginger", "garlic", "tomatoes", "turmeric", "dhania jeera powder", "Mom''s rajma masala", "red chili powder", "salt", "cilantro", "lemon"], "link": "", "minutes": 60, "protein": "Beans", "source": "Mom", "steps": ["Optional: soak the beans in boiling water for a few hours. Mom says you can skip it; the Instant Pot cooks them well either way.", "Instant Pot on sauté: heat some oil, add jeera and hing.", "Once the jeera browns, add chopped onion, then ginger and garlic. Sauté.", "Add chopped tomatoes (3 to 4) and cook until soft.", "Add masala: 1 tsp haldi, 3 tsp dhania jeera, 1 tsp rajma powder (the one Mom gave you), chili powder to taste. Sauté.", "Add 4 cups water, salt and the beans. Pressure cook 45 minutes.", "Finish with cilantro, and lemon if you want it."], "tweak": "From Mom''s texts. Still to ask her: which beans and how many cups, and whether soaked beans need less than 45 minutes. About an hour start to finish, so it''s a weekend or make-ahead dinner.", "veg": "Onion, tomato, cilantro"}'::jsonb),
  ('box/sarahsvegankitchen-com-recipes-chili-garlic-silken-tofu', 'box', '{"at": "2026-10-21T22:30:00Z", "carb": "Rice", "cuisine": "Chinese", "dish": "Chili Garlic Silken Tofu", "id": "box-sarahsvegankitchen-com-recipes-chi", "ingredients": ["silken tofu", "scallions", "garlic", "brown sugar", "soy sauce", "rice vinegar", "chili crisp", "sesame seeds", "toasted sesame oil", "jasmine rice", "baby bok choy"], "link": "https://sarahsvegankitchen.com/recipes/chili-garlic-silken-tofu/", "minutes": 10, "protein": "Silken tofu", "source": "Sarah''s Vegan Kitchen", "steps": ["Start the rice.", "Slide the block of silken tofu onto a plate and slice it.", "Stir garlic, scallions, brown sugar, soy sauce, rice vinegar and chili crisp into a sauce.", "Spoon the sauce over the tofu. Finish with sesame seeds and a drizzle of sesame oil.", "Serve with the rice and quick garlicky bok choy on the side."], "tweak": "The recipe is just the tofu, so add rice and a green side to make it dinner. Steps are condensed; follow the recipe page for the exact method.", "veg": "Scallions, plus a green side"}'::jsonb),
  ('staples/list', 'staples', '{"items": ["salt", "oil", "olive oil", "coconut oil", "toasted sesame oil", "garlic", "ginger", "onion", "cumin seeds", "cumin", "turmeric", "red chili powder", "chili powder", "coriander powder", "garam masala", "kasuri methi", "mustard seeds", "red pepper flakes", "basmati rice", "jasmine rice", "soy sauce", "rice vinegar", "maple syrup", "cornstarch", "dijon mustard", "tomato paste", "sesame seeds", "vegetable broth"]}'::jsonb),
  ('weeks/2026-10-26', 'weeks', '{"nights": {"fri": {"kind": "out", "label": "Vansh & Kruti''s wedding events", "note": "Charleston. No dinner time on the calendar yet."}, "mon": {"cook": "nihal", "kind": "cook", "options": [{"carb": "Rotis", "cuisine": "Indian", "dish": "Paneer Bhurji", "id": "paneer-bhurji", "ingredients": ["paneer", "frozen peas", "onion", "tomatoes", "green chili", "ginger", "garlic", "cumin seeds", "turmeric", "red chili powder", "garam masala", "kasuri methi", "cilantro", "lemon", "rotis", "oil", "salt"], "link": "https://www.indianhealthyrecipes.com/paneer-bhurji-recipe/", "minutes": 25, "protein": "Paneer", "source": "Swasthi''s Recipes", "steps": ["Crumble the paneer. If it''s store-bought, soak it in hot water while you start the masala.", "Fry cumin, then onion and green chili until golden.", "Add ginger and garlic, then tomatoes and the ground spices. Cook until soft and jammy.", "Stir in the peas, then the drained paneer. Cook 2 to 3 minutes.", "Finish with kasuri methi, cilantro and lemon. Warm the rotis."], "tweak": "Peas instead of the optional capsicum.", "veg": "Peas, onion, tomato"}, {"carb": "Rotis", "cuisine": "Indian", "dish": "Matar Paneer", "id": "matar-paneer", "ingredients": ["paneer", "frozen peas", "onion", "tomatoes", "cashews", "ginger", "garlic", "green chili", "cumin seeds", "turmeric", "red chili powder", "garam masala", "kasuri methi", "cream", "cilantro", "rotis", "oil", "salt"], "link": "https://www.indianhealthyrecipes.com/matar-paneer-mutter-masala/", "minutes": 30, "protein": "Paneer", "source": "Swasthi''s Recipes", "steps": ["Blend sautéed onion, tomato and cashews into a smooth paste.", "Cook the paste with ginger, garlic and the ground spices until the oil separates.", "Add water and peas and simmer until the peas are tender.", "Add paneer cubes, kasuri methi and a splash of cream. Simmer 2 minutes.", "Top with cilantro and serve with rotis."], "veg": "Peas, onion, tomato"}, {"carb": "Rice", "cuisine": "Indian", "dish": "Kerala Egg Curry", "id": "kerala-egg-curry", "ingredients": ["eggs", "coconut milk", "onion", "tomatoes", "ginger", "garlic", "green chili", "curry leaves", "mustard seeds", "turmeric", "red chili powder", "coriander powder", "garam masala", "coconut oil", "spinach", "basmati rice", "salt"], "link": "https://www.indianhealthyrecipes.com/kerala-egg-curry/", "minutes": 30, "protein": "Eggs", "source": "Swasthi''s Recipes", "steps": ["Start the rice and hard-boil the eggs.", "Splutter mustard seeds and curry leaves in coconut oil. Add onion, ginger, garlic and chili.", "Add tomatoes and the ground spices and cook until soft.", "Pour in coconut milk, add the peeled eggs and simmer 5 minutes.", "Wilt the spinach in a pan with a little garlic and salt on the side."], "tweak": "Garlicky spinach on the side for a veggie.", "veg": "Spinach side, onion, tomato"}], "time": "19:30"}, "sat": {"kind": "out", "label": "Vansh & Kruti''s wedding", "note": "Charleston. No dinner time on the calendar yet."}, "sun": {"kind": "order", "label": "Order in", "note": "You land at EWR at 5:40pm and should be home around 7."}, "thu": {"kind": "out", "label": "Eat at the airport", "note": "9:42pm flight from EWR. Leave by 7:15pm."}, "tue": {"cook": "prithvi", "kind": "cook", "options": [{"carb": "Corn tortillas", "cuisine": "Mexican", "dish": "Easy Black Bean Tacos", "id": "black-bean-tacos", "ingredients": ["black beans", "corn tortillas", "red cabbage", "avocado", "feta", "limes", "cilantro", "onion", "garlic", "cumin", "chili powder", "salsa verde", "olive oil", "salt"], "link": "https://cookieandkate.com/easy-black-bean-tacos-recipe/", "minutes": 25, "protein": "Black beans, feta", "source": "Cookie and Kate", "steps": ["Simmer the black beans with onion, garlic, cumin and chili powder. Mash a few.", "Toss shredded cabbage with lime, cilantro, olive oil and salt.", "Warm the tortillas in a dry pan.", "Fill with beans, slaw, avocado, feta and salsa verde."], "veg": "Cabbage slaw, avocado"}, {"carb": "Flour tortillas", "cuisine": "Mexican", "dish": "Kale and Black Bean Burritos", "id": "kale-black-bean-burritos", "ingredients": ["black beans", "kale", "large flour tortillas", "cheddar or monterey jack", "salsa", "limes", "cilantro", "garlic", "cumin", "olive oil", "salt"], "link": "https://cookieandkate.com/simple-kale-and-black-bean-burritos/", "minutes": 30, "protein": "Black beans, cheese", "source": "Cookie and Kate", "steps": ["Sauté chopped kale with garlic until wilted. Season with lime and salt.", "Warm the black beans with cumin and a splash of water.", "Fill tortillas with beans, kale, cheese and salsa and roll them up.", "Crisp each burrito seam-side down in a hot pan."], "veg": "Kale"}, {"carb": "Rice", "cuisine": "Chinese-American", "dish": "Crispy Sesame Tofu", "id": "crispy-sesame-tofu", "ingredients": ["extra-firm tofu", "broccoli", "jasmine rice", "cornstarch", "soy sauce", "maple syrup", "rice vinegar", "toasted sesame oil", "sriracha", "ginger", "garlic", "sesame seeds", "scallions", "oil"], "link": "https://www.loveandlemons.com/sesame-tofu-recipe/", "minutes": 30, "protein": "Tofu", "source": "Love and Lemons", "steps": ["Start the rice. Press and cube the tofu and toss it in cornstarch.", "Pan-fry the tofu until crisp on all sides.", "Steam or roast the broccoli.", "Simmer soy sauce, maple, vinegar, sesame oil, ginger, garlic and sriracha until glossy, then toss with the tofu.", "Serve over rice with broccoli, sesame seeds and scallions."], "veg": "Broccoli"}], "time": "19:30"}, "wed": {"cook": "nihal", "kind": "cook", "options": [{"carb": "Ditalini", "cuisine": "Italian", "dish": "Quick Pasta and Chickpeas", "id": "pasta-e-ceci", "ingredients": ["chickpeas", "ditalini", "spinach", "parmesan", "tomato paste", "garlic", "fresh rosemary", "red pepper flakes", "vegetable broth", "olive oil", "salt"], "link": "https://smittenkitchen.com/2017/10/quick-pasta-and-chickpeas-pasta-e-ceci/", "minutes": 30, "protein": "Chickpeas", "source": "Smitten Kitchen", "steps": ["Sizzle garlic, rosemary and pepper flakes in olive oil.", "Stir in tomato paste, then the chickpeas and broth.", "Add the ditalini and simmer until tender and stewy.", "Stir in spinach until wilted. Finish with parmesan and olive oil."], "tweak": "Spinach stirred in for a veggie.", "veg": "Spinach"}, {"carb": "Short pasta", "cuisine": "Mediterranean", "dish": "Pea and Chickpea Pasta Salad", "id": "pea-chickpea-pasta-salad", "ingredients": ["chickpeas", "short pasta", "frozen peas", "arugula", "feta", "lemon", "fresh mint", "dijon mustard", "garlic", "olive oil", "salt"], "link": "https://www.loveandlemons.com/pea-chickpea-pasta-salad/", "minutes": 25, "protein": "Chickpeas", "source": "Love and Lemons", "steps": ["Cook the pasta, dropping the peas in for the last minute. Drain and rinse cool.", "Whisk lemon, olive oil, dijon, garlic and salt.", "Toss pasta and peas with chickpeas, greens, feta, mint and the dressing."], "veg": "Peas, greens"}, {"carb": "Orzo", "cuisine": "Greek-inspired", "dish": "One-Pot Lemon Orzo", "id": "lemon-orzo", "ingredients": ["orzo", "cannellini beans", "spinach", "lemon", "parmesan", "garlic", "vegetable broth", "olive oil", "salt"], "link": "https://www.loveandlemons.com/lemon-orzo/", "minutes": 25, "protein": "White beans", "source": "Love and Lemons", "steps": ["Toast the orzo in olive oil with garlic.", "Add broth and simmer, stirring, until creamy.", "Stir in the white beans and spinach until warm and wilted.", "Finish with lemon zest, lemon juice and parmesan."], "tweak": "White beans stirred in for protein.", "veg": "Spinach"}], "time": "19:30"}}, "note": "Three cook nights, then Charleston for Vansh & Kruti''s wedding. Ingredient lists were written by Claude without reading the recipe pages, so check quantities on the recipe before you shop.", "plannedAt": "2026-10-21", "shelves": {"arugula": "produce", "avocado": "produce", "basmati rice": "pantry", "black beans": "pantry", "broccoli": "produce", "cannellini beans": "pantry", "cashews": "pantry", "cheddar or monterey jack": "dairy", "chickpeas": "pantry", "cilantro": "produce", "coconut milk": "pantry", "corn tortillas": "pantry", "cream": "dairy", "curry leaves": "produce", "ditalini": "pantry", "eggs": "dairy", "extra-firm tofu": "dairy", "feta": "dairy", "fresh mint": "produce", "fresh rosemary": "produce", "frozen peas": "frozen", "garlic": "produce", "ginger": "produce", "green chili": "produce", "jasmine rice": "pantry", "kale": "produce", "large flour tortillas": "pantry", "lemon": "produce", "limes": "produce", "onion": "produce", "orzo": "pantry", "paneer": "dairy", "parmesan": "dairy", "red cabbage": "produce", "rotis": "pantry", "salsa": "pantry", "salsa verde": "pantry", "scallions": "produce", "short pasta": "pantry", "spinach": "produce", "tomatoes": "produce"}, "weekOf": "2026-10-26"}'::jsonb),
